const input = $input.first().json;
const body = input.body || input;
const owner = body.owner || $env.GITHUB_OWNER || '';
let repos = body.repos || [];
if (typeof repos === 'string') { try { repos = JSON.parse(repos); } catch(e) { repos = [repos]; } }
const since = body.since || new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
const until = body.until || new Date().toISOString();
if (!owner) throw new Error('owner가 설정되지 않았습니다.');
if (!repos.length) throw new Error('repos가 비어 있습니다.');
return repos.map(repo => ({ json: { owner, repo, since, until } }));

// fullResponse:true 모드에서 응답 body를 추출, 커밋 0개여도 항상 1개 아이템 반환
const resp = $input.first().json;
const commits = Array.isArray(resp.body) ? resp.body : (Array.isArray(resp) ? resp : []);
const initItem = $('Init Params').first().json;
return [{ json: { commits, owner: initItem.owner, repo: initItem.repo, since: initItem.since, until: initItem.until } }];

const d = $input.first().json;
const commits = d.commits || [];
const owner = d.owner || "";
const repo = d.repo || "";

const shas = commits.slice(0, 5).map(c => c.sha).filter(Boolean);
const commitMessages = commits.map(c => c.commit?.message || "").slice(0, 20);
const activeDays = new Set(commits.map(c => (c.commit?.author?.date || "").substring(0, 10)).filter(Boolean));

// 커밋 0개면 OpenAI 호출 없이 빈 결과 바로 반환
if (commits.length === 0) {
  return [{ json: {
    _skip_llm: true,
    agent_id: "WBS-MOB",
    repo,
    repo_type: "mobile",
    call_flow: [],
    design_gaps: [],
    commit_count: 0,
    active_days: 0,
    screens: [],
    commit_messages: [],
    error: null
  } }];
}

return [{ json: { owner, repo, shas, commit_count: commits.length, active_days: activeDays.size, commit_messages: commitMessages } }];

// 커밋 없는 경우 skip 패스스루
const prevData = $('Extract Commit Info').first().json;
if (prevData._skip_llm) {
  return [{ json: { _skip_llm: true, _passthrough: prevData } }];
}

// 관련 파일 필터링 후 OpenAI 요청 body 생성
const commitData = $input.first().json;
const allFiles = commitData.files || [];

const targetPatterns = ["screens/", "pages/", "navigation/", "api/", "services/"];
const targetExt = /\.(swift|kt|dart|tsx|jsx|js|ts)$/;
const filteredFiles = allFiles
  .filter(f => f.filename && (targetPatterns.some(p => f.filename.toLowerCase().includes(p)) || targetExt.test(f.filename)))
  .map(f => ({ filename: f.filename, patch: (f.patch || '').substring(0, 800) }));

const targetFiles = filteredFiles.length > 0 ? filteredFiles :
  allFiles.slice(0, 5).map(f => ({ filename: f.filename, patch: (f.patch || '').substring(0, 800) }));

const codeSnippet = JSON.stringify(targetFiles).substring(0, 2000);
const prompt = 'Analyze mobile code changes and extract screen transitions and API calls. Return ONLY JSON:\n{\"screens\":[{\"name\":\"\",\"route\":\"\",\"actions\":[\"\"]}],\"call_flow\":[{\"from\":\"\",\"to\":\"\",\"trigger\":\"\"}]}\n\nCode changes:\n' + codeSnippet;

return [{ json: {
  _meta: { repo: prevData.repo, owner: prevData.owner, commit_count: prevData.commit_count, active_days: prevData.active_days, commit_messages: prevData.commit_messages },
  model: 'gpt-4.1-mini',
  messages: [{ role: 'user', content: prompt }],
  stream: false
} }];

// 커밋 없는 skip 패스스루 처리
const buildReq = $('Build Ollama Request').first().json;
if (buildReq._skip_llm) {
  return [{ json: buildReq._passthrough }];
}

const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
const meta = buildReq._meta || {};

let parsed;
try {
  const m = raw.match(/```json\s*([\s\S]*?)```/) || raw.match(/(\{[\s\S]*\})/);
  const jsonStr = m ? (m[1] || m[0]) : '{}';
  parsed = JSON.parse(jsonStr.trim());
} catch (e) {
  parsed = { screens: [], call_flow: [] };
}

return [{ json: {
  agent_id: 'WBS-MOB',
  repo: meta.repo || '',
  repo_type: 'mobile',
  call_flow: parsed.call_flow || [],
  design_gaps: [],
  commit_count: meta.commit_count || 0,
  active_days: meta.active_days || 0,
  screens: parsed.screens || [],
  commit_messages: meta.commit_messages || [],
  error: null
} }];

// 여러 repo 결과 취합
const items = $input.all();
if (items.length === 1) return [items[0]];
return [{ json: {
  agent_id: 'WBS-MOB',
  results: items.map(i => i.json),
  error: null
} }];
